using UnityEngine;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Workshop {
public class BurnoutEffects:MonoBehaviour {
 int observedReset=-1;FinchVehicle car;ParticleSystem[] smoke;TrailRenderer[,] tracks;int[] segment=new int[4];bool[] wasActive=new bool[4];Material material;Texture2D texture;public int ActiveEmitters{get;private set;}
 public static bool ShouldSmoke(bool grounded,float slip,float surfaceSpeed,float roadSpeed,float torque,float throttle,bool locked)=>grounded&&!locked&&throttle>.2f&&Mathf.Abs(torque)>30&&Mathf.Abs(slip)>.15f&&surfaceSpeed-roadSpeed>2.5f;
 void Start(){car=GetComponent<FinchVehicle>();smoke=new ParticleSystem[4];tracks=new TrailRenderer[4,6];texture=new Texture2D(32,32,TextureFormat.RGBA32,false);for(int y=0;y<32;y++)for(int x=0;x<32;x++){float r=new Vector2((x-15.5f)/15.5f,(y-15.5f)/15.5f).magnitude;texture.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01(1-r)*.5f));}texture.Apply();material=new Material(Shader.Find("Sprites/Default")){mainTexture=texture};
  for(int i=0;i<4;i++){var g=new GameObject("Wheel "+i+" contact smoke | visual only");g.transform.SetParent(transform,false);var ps=g.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.loop=true;main.playOnAwake=false;main.simulationSpace=ParticleSystemSimulationSpace.World;main.startLifetime=new ParticleSystem.MinMaxCurve(.5f,1.1f);main.startSpeed=new ParticleSystem.MinMaxCurve(.5f,1.2f);main.startSize=new ParticleSystem.MinMaxCurve(.16f,.38f);main.startColor=new Color(.65f,.65f,.65f,.35f);main.maxParticles=150;var fade=ps.colorOverLifetime;fade.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(1,0),new GradientAlphaKey(.75f,.35f),new GradientAlphaKey(0,1)});fade.color=gradient;main.gravityModifier=-.05f;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=24;shape.radius=.06f;var emission=ps.emission;emission.rateOverTime=0;ps.GetComponent<ParticleSystemRenderer>().sharedMaterial=material;ps.Play();smoke[i]=ps;
   for(int j=0;j<6;j++){var trail=new GameObject("Wheel "+i+" rubber segment "+j+" | visual only").AddComponent<TrailRenderer>();trail.transform.SetParent(transform,false);trail.alignment=LineAlignment.TransformZ;trail.sharedMaterial=material;trail.startColor=new Color(.025f,.025f,.025f,.6f);trail.endColor=new Color(.025f,.025f,.025f,0);trail.startWidth=.16f;trail.endWidth=.14f;trail.time=6;trail.minVertexDistance=.08f;trail.emitting=false;trail.enabled=false;tracks[i,j]=trail;}
  }
 }
 void Update(){if(car==null||smoke==null)return;if(observedReset!=car.ResetSequence){observedReset=car.ResetSequence;foreach(var ps in smoke)ps.Clear();foreach(var tr in tracks){tr.emitting=false;tr.Clear();tr.enabled=false;}for(int i=0;i<4;i++)wasActive[i]=false;}ActiveEmitters=0;for(int i=0;i<4;i++){var wheel=car.Wheels[i];bool ground=wheel.GetGroundHit(out var hit);float surface=Mathf.Abs(wheel.rpm)*2*Mathf.PI*wheel.radius/60;float road=ground?Mathf.Abs(Vector3.Dot(car.Body.GetPointVelocity(hit.point),transform.forward)):0;bool active=ShouldSmoke(ground,hit.forwardSlip,surface,road,wheel.motorTorque,car.Throttle,car.controlsLocked||(!Application.isFocused&&!car.externalInput));bool beginning=active&&!wasActive[i];if(beginning)segment[i]=(segment[i]+1)%6;var track=tracks[i,segment[i]];if(ground){smoke[i].transform.SetPositionAndRotation(hit.point+hit.normal*.04f,Quaternion.LookRotation(hit.normal));track.transform.position=hit.point+hit.normal*.012f;track.transform.rotation=Quaternion.LookRotation(hit.normal);}if(beginning){track.emitting=false;track.Clear();track.enabled=true;}var emission=smoke[i].emission;emission.rateOverTime=active?Mathf.Clamp((surface-road)*4,12,65):0;track.emitting=active;wasActive[i]=active;if(active)ActiveEmitters++;}}
 void OnDestroy(){if(smoke!=null)foreach(var s in smoke)if(s!=null)Destroy(s.gameObject);if(tracks!=null)foreach(var t in tracks)if(t!=null)Destroy(t.gameObject);if(material!=null)Destroy(material);if(texture!=null)Destroy(texture);}
}
}
